entries[86640] = { ["name"] = "Lord Rottingtons geheimes Irrwischbuch", ["text"] = "Wirken in 3 sek. 5\nTools: Schreibzeug des Virtuosen\nReagenzien:\nWiderstandsfähiges Pergament (10), Flüchtiges Leben (20)\nLord Rottingtons geheimes Irrwischbuch\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+191 Ausdauer\n+127 Intelligenz\n+91 Willenskraft\nErhöht Eure Meisterschaftswertung um + 74.\n81" }
entries[86641] = { ["name"] = "Handbuch der Dungeonerkundung", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nWiderstandsfähiges Pergament (10), Infernotinte (8), Flüchtiges Leben (24), Flüchtiges Wasser (6)\nHandbuch der Dungeonerkundung\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+252 Ausdauer\n+168 Intelligenz\nErhöht Eure Meisterschaftswertung um + 107.\n85\nAnlegen: Erhöht die Trefferwertung um 116." }
entries[86642] = { ["name"] = "Göttlicher Begleiter", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nWiderstandsfähiges Pergament (10), Infernotinte (8), Flüchtiges Leben (24), Flüchtige Luft (6)\nGöttlicher Begleiter\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+252 Ausdauer\n+168 Intelligenz\n+120 Willenskraft\n85\nAnlegen: Erhöht die Tempowertung um 98." }
entries[86643] = { ["name"] = "Schlachtfoliant", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nWiderstandsfähiges Pergament (10), Infernotinte (8), Flüchtiges Leben (24), Flüchtiges Feuer (6)\nSchlachtfoliant\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+237 Ausdauer\n+158 Intelligenz\nErhöht Eure Meisterschaftswertung um + 105.\n85\nAnlegen: Erhöht Eure Abhärtungswertung um 105." }
entries[86644] = { ["name"] = "Origamischlamm", ["text"] = "Wirken in 3 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nWiderstandsfähiges Pergament (3)\nDiese besondere Kreation benötigt eine Menge klatschnasses Pergament und Tinte.\nBenutzen: Setzt einige kleine, tintengetränkte Schlamme am Boden ab. (10 Sek. Abklingzeit)" }
entries[86645] = { ["name"] = "Origamistein", ["text"] = "Wirken in 3 sek.\nTools: Schreibzeug des Virtuosen\nReagenzien:\nWiderstandsfähiges Pergament (3)\nBenutzen: Stellt einen Stein ab. (30 Sek. Abklingzeit)" }
