entries[86647] = { ["name"] = "Geätztes Horn", ["text"] = "Wirken in 3 sek. 5\nTools: Schreibzeug des Virtuosen\nReagenzien:\nInfernotinte (4), Gereinigtes Drachenhorn\nGeätztes Horn\nWird beim Anlegen gebunden\nRelikt\n+72 Stärke\n+108 Ausdauer\nErhöht Eure Meisterschaftswertung um + 48.\n\nPrismatischer Sockel\n\n81\nAnlegen: Erhöht Eure Waffenkundewertung um 48." }
entries[86648] = { ["name"] = "Handbuch der Ebenen", ["text"] = "Wirken in 3 sek. 5\nTools: Schreibzeug des Virtuosen\nReagenzien:\nWiderstandsfähiges Pergament (10), Infernotinte (2), Flüchtiges Wasser (2), Flüchtige Luft (2), Flüchtige Erde (2), Flüchtiges Feuer (2)\nHandbuch der Ebenen\nWird beim Anlegen gebunden\nRelikt\n+108 Ausdauer\n+72 Intelligenz\n\nPrismatischer Sockel\n\n81\nAnlegen: Erhöht die Trefferwertung um 52.\nAnlegen: Erhöht die Tempowertung um 42." }
entries[86649] = { ["name"] = "Runenbeschriftete Drachenschuppe", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nInfernotinte (8), Flüchtiges Leben (24), Flüchtiges Feuer (6), Schuppenfragment von Todesschwinge\nRunenbeschriftete Drachenschuppe\nWird beim Anlegen gebunden\nRelikt\n+72 Beweglichkeit\n+108 Ausdauer\n\nPrismatischer Sockel\n\n81\nAnlegen: Erhöht die Trefferwertung um 48.\nAnlegen: Erhöht Eure Waffenkundewertung um 48." }
