entries[86698] = { ["name"] = "Wächter der Uralten Könige", ["text"] = "30 Meter Reichweite\nSofort\nBeschwört einen Wächter der Uralten Könige, der Euch 30 Sek. lang beschützt. Der Wächter der Uralten Könige wird Euer aktuelles Ziel angreifen. Sowohl Eure Angriffe als auch die Eures Wächters der Uralten Könige werden Euch mit Uralter Kraft erfüllen, die entfesselt wird, wenn der Wächter seinen Abschied nimmt." }
