entries[86700] = { ["name"] = "Uralte Kraft", ["text"] = "Sofort\nStärke um 1% erhöht. Wenn Euer Wächter der Uralten Könige verschwindet, werdet Ihr 'Uralter Furor' entfesseln. Dieser Effekt verursacht 234 Heiligschaden, der unter allen Gegnern im Umkreis von 10 Metern aufgeteilt wird." }
